/* Scroll-driven entrances, CSS only. An element fades in, rises 22px and sharpens from a
   6px blur over its first 220px in the window (animation-timeline: view()). A fixed px
   range (not a % of the element) means tall cards that start on the first screen are
   already settled at load. --plumeform-step (0, 1, 2 …) starts an item 40px later, for
   staggered lists. Browsers without scroll timelines, and reduced motion, show everything
   in place. */
@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .plumeform-reveal-rise,
    .plumeform-reveal-fade {
      animation: plumeform-reveal-rise cubic-bezier(0.2, 0.8, 0.2, 1) both;
      animation-timeline: view();
      animation-range: entry calc(var(--plumeform-step, 0) * 40px) entry calc(220px + var(--plumeform-step, 0) * 40px);
    }
    .plumeform-reveal-fade {
      animation-name: plumeform-reveal-fade;
    }
  }
}

@keyframes plumeform-reveal-rise {
  from {
    opacity: 0;
    transform: translateY(22px);
    filter: blur(6px);
  }
}
@keyframes plumeform-reveal-fade {
  from { opacity: 0; }
}

/* Content swapped by a click (a tab, a billing toggle) comes in quickly: give the new
   content a fresh React key to replay it. */
.plumeform-swap-in {
  animation: plumeform-reveal-swap 340ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
@keyframes plumeform-reveal-swap {
  from { opacity: 0; transform: translateY(6px); }
}
@media (prefers-reduced-motion: reduce) {
  .plumeform-swap-in { animation: none; }
}

import type { CSSProperties, ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./plumeform-reveal.css";

/** rise: fade + 22px lift + blur to sharp · fade: opacity only */
export type PlumeformRevealEffect = "rise" | "fade";

/** The class for an effect, to put straight on your own element. */
export function plumeformReveal(effect: PlumeformRevealEffect = "rise") {
  return `plumeform-reveal-${effect}`;
}

/** Inline style for a staggered item: each step starts 40px of scroll later. */
export function plumeformRevealStyle(step = 0): CSSProperties {
  return { "--plumeform-step": step } as CSSProperties;
}

/** Class for content that should replay a short 340ms swap-in when its React key changes. */
export const plumeformSwapIn = "plumeform-swap-in";

export interface PlumeformRevealProps {
  /** what happens as it enters the window */
  effect?: PlumeformRevealEffect;
  /** stagger position in a list (0, 1, 2 …) */
  step?: number;
  /** the element to render */
  as?: "div" | "li" | "p" | "span" | "section";
  children?: ReactNode;
  className?: string;
}

/** Wraps content in a CSS scroll-driven entrance. Static HTML and old browsers show it in place. */
export function PlumeformReveal({ effect = "rise", step = 0, as: Tag = "div", children, className }: PlumeformRevealProps) {
  return (
    <Tag className={cn(plumeformReveal(effect), className)} style={plumeformRevealStyle(step)}>
      {children}
    </Tag>
  );
}
